/** One user interaction, captured as it happens. The unit of evidence about
 * what this user understands. */
export type Interaction = {
  /** Where it sits. A typed turn is a message in its own thread; an opening
   * is not a message at all, so it is addressed by the parent message its
   * highlight lands in - which is also where a citation of it should
   * navigate. */
  at:
    | { type: "turn"; thread: ThreadId; index: number }
    | { type: "opening"; thread: ThreadId; parent: ThreadId; index: number };
  /** The thread's seed, then its blocks before the turn, with their indices.
   * Identical across interactions in the same thread up to their split point -
   * the prompt cache depends on that. */
  prefix: { seed: string | undefined; messages: ReadonlyArray<{ index: number; message: Message }> };
  /** For "opening", the action label; for "typed", the turn's text. */
  text: string;
};

/** The interaction the user just made: a turn that landed at `index` in
 * `thread`, or the opening of a freshly opened `thread`. */
export function interactionAt(
  tree: ThreadTree,
  at: Interaction["at"],
): Interaction;
